package com.andye.warmod.radar.client;
import com.andye.warmod.radar.*;import com.andye.warmod.radar.network.*;import java.util.*;import net.minecraft.resources.Identifier;
public final class ClientRadarState{public static final ClientRadarState INSTANCE=new ClientRadarState();private final Map<UUID,ClientRadarTrack> activeTracks=new LinkedHashMap<>();private final Map<UUID,ClientRadarImpact> recentImpacts=new LinkedHashMap<>();private final ClientRadarTerrainCache terrainCache=new ClientRadarTerrainCache();private final ClientRadarClock clock=new ClientRadarClock();private UUID selectedTrackId;private boolean subscribed,followSelectedTrack;private long lastSnapshotServerGameTime;private Identifier dimensionId;private ClientRadarState(){}public void open(ClientboundOpenRadarPayload p){if(dimensionId!=null&&!dimensionId.equals(p.dimensionId()))clear();subscribed=true;dimensionId=p.dimensionId();clock.synchronize(p.serverGameTime());}public void snapshot(ClientboundRadarSnapshotPayload p){if(dimensionId!=null&&!dimensionId.equals(p.dimensionId()))clear();subscribed=true;dimensionId=p.dimensionId();lastSnapshotServerGameTime=p.serverGameTime();clock.synchronize(p.serverGameTime());activeTracks.clear();for(RadarTrackSnapshot t:p.tracks())activeTracks.put(t.trackId(),new ClientRadarTrack(t));recentImpacts.clear();for(RadarImpactSnapshot i:p.impacts())recentImpacts.put(i.rootTrackId(),new ClientRadarImpact(i));if(selectedTrackId!=null&&!activeTracks.containsKey(selectedTrackId)&&!recentImpacts.containsKey(selectedTrackId))selectedTrackId=null;}public void upsert(ClientboundRadarTrackUpsertPayload p){clock.synchronize(p.serverGameTime());activeTracks.compute(p.track().trackId(),(id,old)->{if(old==null)return new ClientRadarTrack(p.track());old.update(p.track());return old;});}public void remove(ClientboundRadarTrackRemovePayload p){activeTracks.remove(p.trackId());if(!recentImpacts.containsKey(p.trackId())&&p.trackId().equals(selectedTrackId))selectedTrackId=null;}public void impact(ClientboundRadarImpactPayload p){recentImpacts.put(p.impact().rootTrackId(),new ClientRadarImpact(p.impact()));}public Collection<ClientRadarTrack> tracks(){return List.copyOf(activeTracks.values());}public Collection<ClientRadarImpact> impacts(){return List.copyOf(recentImpacts.values());}public ClientRadarTrack selected(){return selectedTrackId==null?null:activeTracks.get(selectedTrackId);}public void select(UUID id){selectedTrackId=id;}public UUID selectedTrackId(){return selectedTrackId;}public boolean subscribed(){return subscribed;}public boolean followSelectedTrack(){return followSelectedTrack;}public void toggleFollow(){followSelectedTrack=!followSelectedTrack;}public void disableFollow(){followSelectedTrack=false;}public Identifier dimensionId(){return dimensionId;}public ClientRadarTerrainCache terrainCache(){return terrainCache;}public ClientRadarClock clock(){return clock;}public long lastSnapshotServerGameTime(){return lastSnapshotServerGameTime;}public void clear(){activeTracks.clear();recentImpacts.clear();terrainCache.clear();selectedTrackId=null;subscribed=false;followSelectedTrack=false;dimensionId=null;lastSnapshotServerGameTime=0;}}
